import {
  Mesh,
  PlaneGeometry,
  Group,
  Color,
  CanvasTexture,
  DoubleSide,
  Vector3,
  Vector2,
} from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/tsl';
import gsap from 'gsap';
import { createLabel as createSdfLabel } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{[key:string]:string}} textContent
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {{[key:string]:(obj:any,params:any)=>void}} primitives
 * @property {{fontAtlas:any}} fontAtlas
 */

/**
 * Create a vertical gradient texture matching the CTA specification.
 * @returns {CanvasTexture}
 */
function createGradientTexture() {
  const height = 256;
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0.0, '#ff4450'); // top
  grad.addColorStop(0.55, '#ff2a38'); // middle
  grad.addColorStop(1.0, '#c1121f'); // bottom
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 1, height);
  const tex = new CanvasTexture(canvas);
  tex.minFilter = tex.magFilter = tex.nearestFilter;
  tex.wrapS = tex.wrapT = tex.clampToEdgeWrapping;
  tex.needsUpdate = true;
  return tex;
}

/**
 * Create the CTA button node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root group
  const root = new Group();
  root.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  root.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  root.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // ---------- Button Plane ----------
  const btnWidth = 2.6; // scene units
  const btnHeight = 0.68;
  const geometry = new PlaneGeometry(btnWidth, btnHeight);
  const gradientTex = createGradientTexture();

  const material = new MeshStandardNodeMaterial({
    map: gradientTex,
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22,
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.6,
    side: DoubleSide,
  });

  const buttonMesh = new Mesh(geometry, material);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = true;
  buttonMesh.position.set(0, 0, 0);
  root.add(buttonMesh);

  // ---------- Text Labels ----------
  // CTA label
  const labelText = config.textContent?.['cta-label'] ?? 'BEGIN COMMISSION';
  const label = createSdfLabel({
    text: labelText,
    fontAtlas: ctx.fontAtlas,
    fontSize: 20,
    fontWeight: 700,
    color: '#e8ecf2',
    letterSpacing: 0.08,
    lineHeight: 1,
    align: 'center',
  });
  // Centered on button plane
  label.position.set(0, 0, 0.01);
  root.add(label);

  // Caption
  const captionText = config.textContent?.caption ?? 'NO DEPOSIT REQUIRED';
  const caption = createSdfLabel({
    text: captionText,
    fontAtlas: ctx.fontAtlas,
    fontSize: 9,
    fontWeight: 400,
    color: '#e8ecf2',
    letterSpacing: 0.12,
    lineHeight: 1.4,
    align: 'center',
  });
  // Positioned 0.25 units below the button
  caption.position.set(0, -(btnHeight / 2 + 0.25), 0.01);
  root.add(caption);

  // ---------- Animations ----------
  const timelines = [];

  // Mount (weighted-settle)
  root.scale.set(1.04, 1.04, 1.04);
  const mountTl = gsap.timeline({ paused: true });
  mountTl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  mountTl.play();
  timelines.push(mountTl);

  // Hover animation helpers
  const hoverDuration = 0.18;
  const hoverEase = 'cubic-bezier(0.25,0.46,0.45,0.94)';

  // Press animation helpers
  const pressDuration = 0.12;
  const pressEase = 'cubic-bezier(0.175,0.885,0.32,1.275)';

  // Store original emissive intensity
  const originalEmissiveIntensity = material.emissiveIntensity;

  // Event handlers (to be attached by the consumer)
  const handlers = {
    pointerover: () => {
      gsap.to(root.position, {
        z: 0.06,
        duration: hoverDuration,
        ease: hoverEase,
      });
      gsap.to(material, {
        emissiveIntensity: 2.2,
        duration: hoverDuration,
        ease: hoverEase,
      });
    },
    pointerout: () => {
      gsap.to(root.position, {
        z: 0,
        duration: hoverDuration,
        ease: hoverEase,
      });
      gsap.to(material, {
        emissiveIntensity: originalEmissiveIntensity,
        duration: hoverDuration,
        ease: hoverEase,
      });
    },
    pointerdown: () => {
      gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: pressDuration,
        ease: pressEase,
      });
    },
    pointerup: () => {
      gsap.to(root.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: pressDuration,
        ease: pressEase,
      });
    },
  };

  // Attach handlers container
  root.userData.handlers = handlers;

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.map.dispose();
    material.dispose();

    // Dispose any textures used by text labels (if they expose .dispose)
    if (label?.material?.map?.dispose) label.material.map.dispose();
    if (caption?.material?.map?.dispose) caption.material.map.dispose();

    // Kill GSAP timelines
    timelines.forEach((tl) => tl.kill());

    // Remove references
    root.remove(...root.children);
  };

  // No cinematic primitives to apply as per spec

  return root;
}
